#[test]
fn the_classification_matches_the_binary64_reimplementation_bit_for_bit() {
    // SD-J1.
    let mut sets = 0;
    let mut counts = [0usize; 4];
    let mut layout = Vec::new();
    let mut values = Vec::new();
    let mut expected = Vec::new();
    let mut scales: Vec<(u32, Kind, u64)> = Vec::new();
    let mut extents = Vec::new();
    for line in VECTORS.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "set" => {
                layout.clear();
                values.clear();
                expected.clear();
                scales.clear();
                extents = f[3..].iter().map(|h| hex(h)).collect();
            }
            "row" => {
                layout.push(QuantityMeta {
                    id: QuantityId::Displacement(Dof::from_global(layout.len())),
                    kind: Kind::ALL[f[1].parse::<usize>().unwrap()],
                    body: f[2].parse().unwrap(),
                    input_derived: f[3] == "1",
                });
                values.push(outcome(f[4]));
                expected.push(class(f[5]));
            }
            "scales" => {
                let b: u32 = f[1].parse().unwrap();
                for (k, h) in f[2..].iter().enumerate() {
                    scales.push((b, Kind::ALL[k], u64::from_str_radix(h, 16).unwrap()));
                }
            }
            "end" => {
                let publication = classify_rows(&layout, &values, &extents);
                let got: Vec<RowClass> = publication.rows.iter().map(|r| r.class).collect();
                assert_eq!(got, expected, "set {sets}");
                assert_eq!(publication.body_scales, scales, "set {sets}");
                for c in &got {
                    counts[match c {
                        RowClass::RelativeVerified => 0,
                        RowClass::AbsoluteVerified { .. } => 1,
                        RowClass::InputDerived => 2,
                        RowClass::Unpublishable => 3,
                    }] += 1;
                }
                sets += 1;
            }
            _ => {}
        }
    }
    // 405 sets, and A1's four (ROOT's ruling on RV19-6).
    assert_eq!(sets, 409);
    assert!(counts.iter().all(|&c| c > 50), "{counts:?}");

fn item_6a_floors_force_and_moment_by_phi_where_it_binds_and_nowhere_else() {
    use super::super::recover::{End, Kind, QuantityMeta};
    use super::super::source::Component;
    use super::super::verify::phi_512;
    let row = |kind: Kind, component: Component| QuantityMeta {
        id: QuantityId::EndAction {
            member: 1,
            end: End::I,
            component,
        },
        kind,
        body: 0,
        input_derived: false,
    };
    let layout = vec![
        row(Kind::Force, Component::Ux),
        row(Kind::Moment, Component::Rx),
    ];
    let values = |f: f64, m: f64| vec![Binary64Outcome::Normal(f), Binary64Outcome::Normal(m)];
    let extents = [0.0];
    // Φ binds on force (S* = 1e-200 < Φ_fo = 1e-150): the row becomes
    // absolute_verified with b = fl↑(2^-64·Φ); moment is not floored (Φ_mo = 0).
    let v = values(1e-200, 3.0);
    let plain = classify_rows(&layout, &v, &extents);
    let floored = classify_rows_floored(&layout, &v, &extents, Some(&[[1e-150, 0.0]]));
    assert_eq!(plain.rows[0].class, RowClass::RelativeVerified);
    assert_eq!(
        floored.rows[0].class,
        RowClass::AbsoluteVerified {
            bound_bits: absolute_bound(1e-150).to_bits()
        }
    );
    assert_eq!(floored.rows[1].class, plain.rows[1].class);
    let scale = |p: &Publication, k: Kind| {
        f64::from_bits(p.body_scales.iter().find(|s| s.1 == k).unwrap().2)
    };
    assert_eq!(scale(&floored, Kind::Force), 1e-150);
    assert_eq!(scale(&floored, Kind::Moment), 3.0);

