fn operands_whose_stations_or_support_groups_differ_are_withheld() {
    // ROOT's ruling on RV19-3: the stiffness identity and the layout hold
    // only a station's and a group's ids. Station 1 at t = 0.25 (st.1.4 = 0.75)
    // and at t = 0.75 (st.1.4 = 0.25) would combine to A's station doubled
    // (1.5), where Σcᵢ·(case i) is 1.0.
    let a = selected_source(cantilever(0.25, &[1]));
    let b = selected_source(cantilever(0.75, &[1]));
    let c = selected_source(cantilever(0.25, &[]));
    let reason = |o: CombinationOutcome| match o {
        CombinationOutcome::Unresolved { reason, attempts } => {
            assert!(attempts.is_empty());
            reason
        }
        other => panic!("{other:?}"),
    };
    assert_eq!(
        reason(combine(&[(1.0, a.as_ref()), (1.0, b.as_ref())])),
        CombinationReason::OperandsDiffer
    );
    // Group 1 reused under the same id with a different spring set.
    assert_eq!(
        reason(combine(&[(1.0, a.as_ref()), (1.0, c.as_ref())])),
        CombinationReason::OperandsDiffer
    );
    // Equal stations and groups combine: st.1.4 = 2·0.75.

let withheld = |reason| CombinationOutcome::Unresolved {
    reason,
    attempts: Vec::new(),
};
if operands.is_empty() || operands.iter().any(|o| !o.0.is_finite()) {
    return withheld(CombinationReason::NoOperands);
}
if operands.iter().any(|o| !o.1.prep.factors.is_empty()) {
    return withheld(CombinationReason::NestedCombination);
}
let first = operands[0].1;
let identity = first.prep.source.stiffness_encoding();
let (stations, supports) = (first.prep.source.stations(), first.prep.source.supports());
if operands.iter().any(|(_, o)| {
    o.prep.source.stiffness_encoding() != identity
        || o.prep.layout != first.prep.layout
        || o.prep.source.stations() != stations
        || o.prep.source.supports() != supports
}) {
    return withheld(CombinationReason::OperandsDiffer);
}

#[test]
fn the_sas_norm_is_the_larger_of_the_one_and_infinity_norms() {
    // RV19-5 (ROOT's ruling): R7 item 6 takes ‖SĀS‖ as the larger of the
    // 1-norm and the ∞-norm, since Lemma C uses the 1-norm and the Theorem's
    // step 5 the ∞-norm. On the controls Ā's triangles differ only by the
    // rounding of |D|B̄ and the ∞-norm is never the smaller, so here one
    // transposed entry of N05's Ā at 256 is raised by 2^20: a column sum then
    // exceeds every row sum, and the block's norm must be the 1-norm.
    let prep = CasePrep::new(models::model("N05").source()).unwrap();
    let group = prepare_group(&prep.source).unwrap();
    let guard = StageGuard::unlimited();
    let shared = build_shared::<4, 8>(256, 320, &prep.source, &group, guard)
        .result
        .unwrap();
    let state = solve_case_at::<4, 8>(&shared, &prep, &group, guard)
        .result
        .unwrap();
    let mut vs = build_verify_shared::<4, 8, 8>(&shared, &prep.source, &group, guard)
        .result
        .unwrap();
    let pattern = &group.structure.pattern;
    let position = &group.ordering.position;
    let mut found = 0;
    for &g in &group.ordering.free {
        for index in pattern.row_range(g) {
            let j = pattern.column(index);
            if j == g || position[j] == usize::MAX {
                continue;
            }
            let t = pattern.transpose(index);
            let original = vs.abar[t];
            if original.is_zero() {
                continue;
            }
            vs.abar[t] = original.mul_pow2(20).unwrap();
            let r = verify_state::<4, 8, 8>(&shared, &vs, &prep, &group, &state, guard)
                .result
                .unwrap();
            vs.abar[t] = original;
            for n in &r.norms {
                let one_larger = n.sas_one.cmp_value(&n.sas_inf) == std::cmp::Ordering::Greater;
                let larger = if one_larger { &n.sas_one } else { &n.sas_inf };
                assert_eq!(n.sas.cmp_value(larger), std::cmp::Ordering::Equal);
                found += usize::from(one_larger);
            }
        }
    }
    assert!(found > 0, "no entry makes the 1-norm the larger");

pub(super) fn scale_at<const L: usize, const R: usize>(
    p: u32,
    q: u32,
    prep: &CasePrep,
    group: &GroupPrep,
    recs: &[Vec<&str>],
) where
    Wide<L>: SupportedWidth,
    Wide<R>: SupportedWidth,
{
    let name = recs[0][1];
    let guard = StageGuard::unlimited();
    let shared = build_shared::<L, R>(p, q, &prep.source, group, guard).result;
    let solved = shared
        .as_ref()
        .map_err(|s| s.clone())
        .and_then(|sh| solve_case_at::<L, R>(sh, prep, group, guard).result);
    if recs[0][3] == "stop" {
        let stop = solved.expect_err(name);
        assert_eq!(stop_name(&stop), recs[0][4], "{name} {p}");
        return;
    }
    let shared = shared.unwrap();
    let solved = solved.unwrap_or_else(|e| panic!("{name} {p}: {e:?}"));
    assert_eq!(
        solved.corrections.to_string(),
        recs[0][4],
        "{name} {p} corrections"

        "abar" => {
            let mut entries: Vec<(usize, usize, usize)> = group.structure.entries().collect();
            entries.sort_unstable();
            let lines: Vec<String> = entries
                .iter()
                .map(|&(r, c, index)| format!("{r} {c} {}", tok(&abar[index])))
                .collect();
            assert_eq!(digest(&lines), f[3], "{name} {p} Ā");
        }
        "erows" => assert_eq!(digest(&erows), f[3], "{name} {p} E rows"),
        "erow" => explicit.push(format!("{} {}", f[3], f[4])),
        "ebody" => {
            let b: usize = f[3].parse().unwrap();
            let eh = e_hat(resolution[b], prep.extents[b]);
            let values = [
                resolution[b][0],
                resolution[b][1],
                eh[0],
                eh[1],
                phi_512(eh[0]),
                phi_512(eh[1]),
            ];
            let got: Vec<String> = values
                .iter()
                .map(|v| format!("{:016x}", v.to_bits()))
                .collect();
            assert_eq!(got, f[4..10].to_vec(), "{name} {p} body {b}");
        }
        other => panic!("{other}"),
    }
}
